<?php
/** Homepage publication catalog/editor/trash/history inside the fixed admin frame; localized tables, private previews and shared raw-data code authoring. */
declare(strict_types=1);
use DBLESSCMS\{HomepageCatalog,Homepages,ContentContext,Components,ContentDocuments,Security,Icons};
use function DBLESSCMS\e;
/** Translate hardcoded Homepage controls; receive key/parameters, return text without mutation. */
$t=static fn(string $key,array $parameters=[]):string=>$context->language->text('homepage.'.$key,$parameters);
/** Build a declared local route; receive route/optional ID, return URL without effects. */
$url=static fn(string $route,string $id=''):string=>$context->base.'/cms-admin/?'.http_build_query(['view'=>$route==='preview'?'plugin':'plugin-panel','plugin'=>'homepage','route'=>$route]+($id!==''?['id'=>$id]:[]));
/** Display known UTC dates without inventing historical values; receive timestamp/null, return UTC display text. */
$date=static fn(?string $value):string=>$value===null||$value===''?'—':str_replace(['T','Z'],[' ',' UTC'],$value);
$repository=new HomepageCatalog($context->store);$snapshot=$repository->read();$data=$snapshot['data'];$revision=$snapshot['revision'];$site=$context->store->read('site');$csrf=Security::token();$readContext=new ContentContext($context->store,$site['data']['template'],$context->base,'home');$effective=(new Homepages($context->store))->resolve($readContext);$active=$effective['id'];$route=$context->route;
/** Output a fixed CSRF/revision hidden-field set; no arguments, writes escaped form metadata without changing storage. */
$hidden=static function(?string $pageRevision=null)use($csrf,$revision,$site):void{?><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="revision" value="<?= e($pageRevision??$revision) ?>"><input type="hidden" name="site_revision" value="<?= e($site['revision']) ?>"><?php };
?>
<div class="homepage-plugin homepage-catalog" data-homepage-catalog data-date-error="<?= e($t('dateInvalid')) ?>" data-network-error="<?= e($t('network')) ?>">
<p class="notice error" data-catalog-status role="alert" hidden></p>
<?php if(in_array($route,['overview','trash'],true)): ?>
<div class="editor-toolbar"><p class="muted"><?= e($t('scheduleHelp')) ?></p><a class="button-primary" href="<?= e($url('new')) ?>"><?= e($t('new')) ?></a></div>
<section class="panel extension-panel"><table class="extension-table" data-homepage-table><thead><tr><?php foreach(['nameField','descriptionField','publishedAt','createdAt','updatedAt','status','action'] as $column): ?><th scope="col"><?= e($t($column)) ?></th><?php endforeach; ?></tr></thead><tbody>
<?php $rows=array_filter($data['homepages'],static fn(array $row):bool=>($row['deletedAt']!==null)===($route==='trash'));uasort($rows,static fn(array $a,array $b):int=>strcmp($b['updatedAt']??'',$a['updatedAt']??'')?:strcmp($a['id'],$b['id']));foreach($rows as $row): $status=Homepages::status($row,$active); ?>
<tr data-homepage-id="<?= e($row['id']) ?>"><td data-label="<?= e($t('nameField')) ?>"><strong><?= e($row['name']) ?></strong></td><td data-label="<?= e($t('descriptionField')) ?>"><?= e($row['description']) ?></td><td data-label="<?= e($t('publishedAt')) ?>"><?= e($row['published']!==null&&($row['publishAt']===''||strtotime($row['publishAt'])<=time())?$date($row['publishAt']):'—') ?></td><td data-label="<?= e($t('createdAt')) ?>"><?= e($date($row['createdAt'])) ?></td><td data-label="<?= e($t('updatedAt')) ?>"><?= e($date($row['updatedAt'])) ?></td><td data-label="<?= e($t('status')) ?>"><span class="status <?= $status==='active'?'published':'' ?>"><?= e($t('state.'.$status)) ?></span><?php if($status==='scheduled'): ?><small><?= e($date($row['publishAt'])) ?></small><?php endif; ?></td><td data-label="<?= e($t('action')) ?>"><div class="row-actions">
<?php if($route==='trash'): ?><form method="post" action="<?= e($context->url('catalog-recover')) ?>" data-catalog-form><?php $hidden(); ?><input type="hidden" name="id" value="<?= e($row['id']) ?>"><button class="icon-button" title="<?= e($t('recover')) ?>" aria-label="<?= e($t('recover')) ?>"><?= Icons::svg('history',$context->base) ?></button></form>
<?php else: $toggle=in_array($status,['active','scheduled'],true)?'deactivate':'activate'; ?>
<form method="post" action="<?= e($context->url('catalog-'.$toggle)) ?>" data-catalog-form><?php $hidden(); ?><input type="hidden" name="id" value="<?= e($row['id']) ?>"><button class="icon-button" title="<?= e($row['protected']&&$toggle==='deactivate'?$t('protected'):$t($toggle)) ?>" aria-label="<?= e($t($toggle)) ?>" <?= $row['protected']&&$toggle==='deactivate'?'disabled':'' ?>><?= Icons::svg($toggle,$context->base) ?></button></form>
<a class="icon-button" href="<?= e($url('editor',$row['id'])) ?>" title="<?= e($t('edit')) ?>" aria-label="<?= e($t('edit')) ?>"><?= Icons::svg('edit',$context->base) ?></a>
<form method="post" action="<?= e($context->url('catalog-remove')) ?>" data-catalog-form data-confirm="<?= e($t('confirmRemove')) ?>"><?php $hidden(); ?><input type="hidden" name="id" value="<?= e($row['id']) ?>"><button class="icon-button danger" title="<?= e($row['protected']?$t('protected'):$t('remove')) ?>" aria-label="<?= e($t('remove')) ?>" <?= $row['protected']?'disabled':'' ?>><?= Icons::svg('trash',$context->base) ?></button></form>
<?php endif; ?></div></td></tr>
<?php endforeach; ?></tbody></table><?php if($rows===[]): ?><p class="empty-state"><?= e($t('empty')) ?></p><?php endif; ?></section>
<?php elseif(in_array($route,['new','editor'],true)):
$entry=$route==='new'?null:($data['homepages'][$id]??throw new \DBLESSCMS\HttpError(404,'Homepage unavailable.','error.not_found'));if($entry!==null&&$entry['deletedAt']!==null)throw new \DBLESSCMS\HttpError(404,'Homepage is removed.','error.not_found');
$body=$entry['draft']??['mode'=>'html','html'=>"<section class=\"section\">\n  <div class=\"container\">\n    <h1>Welcome</h1>\n    <p>Write your homepage content here.</p>\n  </div>\n</section>",'bindings'=>[],'source'=>['plugin'=>'','id'=>''],'publicationAt'=>''];$warnings=(new Components($readContext))->validateBindings($body['bindings']);$sources=ContentDocuments::options($readContext);
?>
<p class="muted"><?= e($t('metadataHelp')) ?></p><?php if($warnings!==[]): ?><p class="notice" role="status"><?= e($t('bindingsWarning',['items'=>implode(', ',$warnings)])) ?></p><?php endif; ?>
<form method="post" action="<?= e($context->url('catalog-save')) ?>" data-catalog-form data-homepage-publication data-sources="<?= e(json_encode($sources,JSON_THROW_ON_ERROR)) ?>" data-source="<?= e(json_encode($body['source'],JSON_THROW_ON_ERROR)) ?>" data-unavailable="<?= e($t('sourceUnavailable')) ?>">
<?php $hidden(); ?><input type="hidden" name="id" value="<?= e($entry['id']??'') ?>"><input type="hidden" name="publicationAt" value="<?= e($body['publicationAt']) ?>" data-publication-utc>
<section class="panel"><div class="field-grid"><label><?= e($t('nameField')) ?><input name="name" maxlength="200" value="<?= e($entry['name']??'') ?>" required></label><label><?= e($t('publicationDate')) ?><input type="datetime-local" step="1" name="publicationLocal" value="<?= e(substr($body['publicationAt'],0,19)) ?>" data-publication-local></label><label><?= e($t('timezone')) ?><select aria-label="<?= e($t('timezone')) ?>" name="timezone" data-publication-timezone><option value="UTC">UTC</option><option value="local"><?= e($t('localTime')) ?></option></select></label></div><label><?= e($t('descriptionField')) ?><textarea name="description" rows="3" maxlength="2000"><?= e($entry['description']??'') ?></textarea></label><label><?= e($t('mode')) ?><select aria-label="<?= e($t('mode')) ?>" name="mode" data-homepage-mode><?php foreach(($entry['protected']??false)?['legacy'=>'legacyMode','html'=>'htmlMode','source'=>'sourceMode']:['html'=>'htmlMode','source'=>'sourceMode'] as $mode=>$label): ?><option value="<?= e($mode) ?>" <?= $mode===$body['mode']?'selected':'' ?>><?= e($t($label)) ?></option><?php endforeach; ?></select></label></section>
<section class="panel" data-homepage-html><?php $markupDefinition=['html'=>$body['html'],'bindings'=>$body['bindings']];require $context->config->root.'/admin/markup-editor.php'; ?></section>
<section class="panel" data-homepage-source><div class="field-grid"><label><?= e($t('sourcePlugin')) ?><select aria-label="<?= e($t('sourcePlugin')) ?>" name="source_plugin" data-source-plugin><?php foreach($sources as $sourceId=>$source): ?><option value="<?= e($sourceId) ?>" <?= $sourceId===$body['source']['plugin']?'selected':'' ?>><?= e($source['name']) ?></option><?php endforeach; if($body['source']['plugin']!==''&&!isset($sources[$body['source']['plugin']])): ?><option value="<?= e($body['source']['plugin']) ?>" selected><?= e($body['source']['plugin']) ?></option><?php endif; ?></select></label><label><?= e($t('sourcePage')) ?><select aria-label="<?= e($t('sourcePage')) ?>" name="source_id" data-source-id><option value="<?= e($body['source']['id']) ?>"><?= e($body['source']['id']) ?></option></select></label></div><p class="notice" role="status" data-source-warning hidden><?= e($t('sourceUnavailable')) ?></p></section>
<p class="notice" data-homepage-legacy><?= e($t('legacyHelp')) ?></p>
<div class="savebar"><p class="muted"><?= e($t('scheduleHelp')) ?></p><div class="homepage-actions"><?php if($entry!==null): ?><a class="button-secondary" target="_blank" rel="noopener" href="<?= e($url('preview',$entry['id'])) ?>"><?= e($t('previewCatalog')) ?></a><?php endif; ?><button class="button-secondary" type="submit" name="publish" value="0" data-publish="0"><?= e($t('catalogSave')) ?></button><button class="button-primary" type="submit" name="publish" value="1" data-publish="1"><?= e($t('publishSchedule')) ?></button></div></div></form>
<?php elseif($route==='history'): ?>
<section class="panel"><h2><?= e($t('catalogHistory')) ?></h2><?php $history=$repository->history();if($history===[]): ?><p class="empty-state"><?= e($t('noHistory')) ?></p><?php endif; foreach($history as $backup): ?><form class="history-row" method="post" action="<?= e($context->url('catalog-restore')) ?>" data-catalog-form data-confirm="<?= e($t('confirmRestore')) ?>"><?php $hidden(); ?><input type="hidden" name="backup" value="<?= e($backup) ?>"><span><?= e(substr($backup,0,22)) ?></span><button class="button-secondary"><?= e($t('restore')) ?></button></form><?php endforeach; ?></section>
<section class="panel"><h2><?= e($t('legacyHistory')) ?></h2><a class="button-secondary" href="<?= e($url('editor')) ?>"><?= e($t('legacyDrafts')) ?></a><?php foreach($context->store->history('home') as $backup): ?><form class="history-row" method="post" action="<?= e($context->url('restore')) ?>" data-catalog-form><?php $hidden($context->store->read('home')['revision']); ?><input type="hidden" name="page_revision" value="<?= e($context->store->read('home')['revision']) ?>"><input type="hidden" name="backup" value="<?= e($backup) ?>"><span><?= e(substr($backup,0,22)) ?></span><button class="button-secondary"><?= e($t('restore')) ?></button></form><?php endforeach; ?></section>
<?php endif; ?>
</div>
